// room-service.order → route items to kitchen / bar / amenities.
const b = $input.first().json.body || {};
const o = b.data || {};
const DRINK = /(water|tea|coffee|juice|wine|beer|cola|soda|espresso|cappuccino|latte|woda|herbata|kawa|sok|piwo)/i;
const AMEN  = /(towel|toiletr|pillow|blanket|slipper|amenit|soap|shampoo|ręcznik|poduszk|kołdr|kapcie)/i;
const groups = { kitchen: [], bar: [], amenities: [] };
for (const it of (o.items || [])) {
  const line = it.qty + '× ' + it.name;
  if (AMEN.test(it.name)) groups.amenities.push(line);
  else if (DRINK.test(it.name)) groups.bar.push(line);
  else groups.kitchen.push(line);
}
const parts = Object.entries(groups).filter(([,v]) => v.length).map(([k,v]) => k.toUpperCase() + ': ' + v.join(', '));
const summary = 'Room ' + (o.room || '?') + ' — ' + parts.join(' | ');
return [{ json: { event: b.event, room: o.room, routing: groups, summary } }];
